<?php
require_once dirname(__DIR__,2).'/core/bootstrap.php';Auth::requireLogin();$db=Database::getInstance()->pdo();if($_SERVER['REQUEST_METHOD']==='POST'){Csrf::verify($_POST['csrf_token']??'');$name=trim($_POST['name']);if($name!==''){$db->prepare('INSERT INTO customers(name,phone,tier_id) VALUES(?,?,?)')->execute(array($name,trim($_POST['phone'])?:null,(int)$_POST['tier_id']?:null));Helper::flash('تمت إضافة الزبون.','success');}Helper::redirect('modules/customers/index.php');}$tiers=$db->query('SELECT * FROM customer_tiers')->fetchAll();$rows=$db->query('SELECT c.*,t.name tier FROM customers c LEFT JOIN customer_tiers t ON t.id=c.tier_id ORDER BY c.id DESC')->fetchAll();$pageTitle='الزبائن';require APP_ROOT.'/includes/header.php';?><div class="page-heading"><div><h1>الزبائن</h1><p>الأرصدة: الموجب إيداع، والسالب دين مستحق</p></div></div><div class="card mb-3"><div class="card-header">إضافة زبون</div><div class="card-body"><form method="post" class="row g-3 align-items-end"><?= Helper::csrfField() ?><div class="col-md-4"><label class="form-label">الاسم</label><input class="form-control" name="name" required></div><div class="col-md-3"><label class="form-label">الهاتف</label><input class="form-control" name="phone"></div><div class="col-md-3"><label class="form-label">الطبقة</label><select class="form-select" name="tier_id"><option value="0">عادي</option><?php foreach($tiers as $t): ?><option value="<?= (int)$t['id'] ?>"><?= Helper::e($t['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-coffee w-100">إضافة</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>الاسم</th><th>الهاتف</th><th>الطبقة</th><th>الرصيد</th><th>النقاط</th><th>مشتريات إجمالية</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= Helper::e($r['name']) ?></td><td><?= Helper::e($r['phone']) ?></td><td><?= Helper::e($r['tier']?:'عادي') ?></td><td class="<?= $r['balance']<0?'text-danger':'' ?>"><?= Helper::money($r['balance']) ?></td><td><?= (int)$r['points'] ?></td><td><?= Helper::money($r['total_purchases']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty-state">لا يوجد زبائن مسجلون</td></tr><?php endif; ?></tbody></table></div></div><?php require APP_ROOT.'/includes/footer.php';
